icons.close=window.LM_ICON_SVGS.close;icons.menu=window.LM_ICON_SVGS.menu;for(const key of ['x','github','telegram']){const path=icons[key].match(/<path d="([^"]+)"/)[1];icons[key]=`<svg class="lm-social-mark" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="${path}" stroke="#b8873d" stroke-width="1.6" stroke-linejoin="round"/><path d="${path}" stroke="#fff8e8" stroke-width=".55" stroke-linejoin="round"/></svg>`}
