const money=n=>'$'+fmt(n);
let previousFocus=null;
function closeModal(){const d=document.getElementById('lm-modal');if(d){d.close();d.remove()}previousFocus?.focus?.();previousFocus=null}
function modal(title,body,actions=''){closeModal();previousFocus=document.activeElement;const d=document.createElement('dialog');d.id='lm-modal';d.className='lm-ui lm-dialog';d.innerHTML=`<button class="lm-icon-button lm-close" aria-label="Close dialog" data-lm-close>${icons.close}</button><h2>${esc(title)}</h2>${body}${actions?`<div class="lm-dialog-actions">${actions}</div>`:''}`;document.body.append(d);d.showModal();d.addEventListener('click',e=>{if(e.target===d||e.target.closest('[data-lm-close]'))closeModal()});d.addEventListener('cancel',e=>{e.preventDefault();closeModal()});return d}
function toast(message){document.querySelector('.lm-toast')?.remove();const t=document.createElement('div');t.className='lm-ui lm-toast';t.role='status';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),3400)}
function brand(){return '<a class="lm-brand" href="/" aria-label="Lemniscate home"><img src="/assets/lemniscate-mark-v2.webp" alt=""><span>LEMNISCATE</span></a>'}
